        return 0
    return fail(f"git-shim: unsupported rev-parse arguments {args!r}")


def cmd_log(repo: Path, args: list[str]) -> int:
    sys.stdout.write("commit head\n\n    git-shim synthetic history\n")
    return 0


def cmd_bundle(repo: Path, args: list[str]) -> int:
    if args and args[0] == "create" and len(args) >= 2:
